        "Text analysis involves examining words, sentences, and paragraphs to extract useful metrics. " +
        "Word frequency analysis is a common technique in natural language processing. " +
        "The average word length in English text is typically around five characters. " +
        "Histograms provide a visual representation of the distribution of numerical data. " +
        "Unique word counts help measure vocabulary richness in a given text sample.";

    [GlobalSetup]
    public void Setup()
    {
        _analyzer = new TextAnalyzer(SampleText);
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

